"""Deterministic command routing only; never execute raw ASR or model text."""
from collections import deque
import re

COMMANDS = {
    '启动云台': 'tracking_start', '开启云台': 'tracking_start',
    '测肤': 'assessment_start', '开始测肤': 'assessment_start',
    '皮肤检测': 'assessment_start', '开始皮肤检测': 'assessment_start',
    '停止云台': 'stop', '停止测肤': 'stop', '停止播报': 'stop',
}


class IntentRouter:
    def __init__(self):
        self.seen = deque(maxlen=128)

    def route(self, session_id, sentence_id, kind, text):
        if kind != 'final':
            return None
        if (not isinstance(session_id,str) or not session_id or
                type(sentence_id) is not int or sentence_id < 0 or
                not isinstance(text,str) or len(text)>4096):
            raise ValueError('invalid_recognition')
        key=(session_id,sentence_id)
        if key in self.seen:
            return None
        self.seen.append(key)
        normalized=re.sub(r'[\s，。！？,.!?：:]+','',text)
        if not normalized:
            return None
        return COMMANDS.get(normalized,'chat')
import unittest
from .voice_intents import IntentRouter


class IntentTests(unittest.TestCase):
    def test_skin_detection_command(self):
        for text in ['皮肤检测。', '开始皮肤检测']:
            self.assertEqual(IntentRouter().route('a',0,'final',text),'assessment_start')
        for text in ['不要皮肤检测','皮肤检测是什么意思','皮肤检测停止云台']:
            self.assertEqual(IntentRouter().route('a',0,'final',text),'chat')

    def test_explicit_commands(self):
        r=IntentRouter()
        for n,(text,want) in enumerate([('启动云台。','tracking_start'),('开始测肤','assessment_start'),('停止云台！','stop'),('停止播报','stop')]):
            self.assertEqual(r.route('a',n,'final',text),want)

    def test_partial_and_replayed_final_do_not_execute(self):
        r=IntentRouter()
        self.assertIsNone(r.route('a',1,'partial','启动云台'))
        self.assertEqual(r.route('a',1,'final','启动云台'),'tracking_start')
        self.assertIsNone(r.route('a',1,'final','启动云台'))
        self.assertEqual(r.route('b',1,'final','启动云台'),'tracking_start')

    def test_negation_and_discussion_are_not_motion_commands(self):
        for text in ['不要启动云台','我说启动云台会怎么样','启动云台然后测肤','云台已启动']:
            self.assertEqual(IntentRouter().route('a',1,'final',text),'chat')
